import base64

template_ui_b64 = ''''''

template_ui = base64.b64decode(template_ui_b64).decode('utf-8')

# Read file
with open('src/components/agent/edit-agent.tsx', 'r') as f:
    lines = f.readlines()

# Find insertion point (before agent-tool-bindings section)
insert_idx = None
for i, line in enumerate(lines):
    if 'agent-tool-bindings' in line and i > 400:
        insert_idx = i - 2
        break

if insert_idx:
    lines.insert(insert_idx, template_ui + '\n')
    with open('src/components/agent/edit-agent.tsx', 'w') as f:
        f.writelines(lines)
    print(f'Template UI inserted at line {insert_idx + 1}')
else:
    print('Insertion point not found')
